#### Setup ####
#run DSSAT simulation via batch_file and create output graph
#Credit for DSSAT R Package
#https://cran.r-project.org/web/packages/DSSAT/index.html
#https://cran.r-project.org/web/packages/DSSAT/citation.html
#install stringi
library(DSSAT)
options(DSSAT.CSM="C:/DSSAT48/DSCSM048.exe")
library(dplyr)
library(ggpubr)
library(ggplot2)
library(hydroGOF)
global_size = 20 
color_palette <- palette.colors(palette = "Okabe-Ito")
color_palette
script_path <- tryCatch(normalizePath(sys.frame(1)$ofile, winslash = "/", mustWork = FALSE), error = function(e) "")
script_dir <- if (nzchar(script_path)) dirname(script_path) else getwd()
dashboard_dir <- file.path(script_dir, "hemp_dss_dashboard_outputs")
dir.create(dashboard_dir, recursive = TRUE, showWarnings = FALSE)
output_workdir <- "D:/OneDrive - University of Florida/ABE_Hemp_DSS_PhD/hemp_r-shiny_webapp/Hemp-DSS-Dashboard/hemp_dss_dashboard"
setwd <- function(dir) {
  if (identical(dir, output_workdir)) {
    dir.create(dashboard_dir, recursive = TRUE, showWarnings = FALSE)
    base::setwd(dashboard_dir)
  } else {
    base::setwd(dir)
  }
}
