##### seasonal analysis - NFREC - NWG - At Grain Maturity _200_plants_112kg_N #### 
filename <- "UFLO0329"
setwd("C:/DSSAT48/Hemp")
batch_file_path <- paste0(getwd(),'/DSSBatch.V48')
write_dssbatch(x=paste0(filename,'.HMX'), trtno=21:29, file_name = batch_file_path)
run_dssat()
plantgro <- read_output('PlantGro.OUT') %>%
  filter(GSTD == 8)  %>%
  mutate(planting=factor(TRNO,labels=planting_dates))

print("NFREC - NWG - At Grain Maturity")
plantgro %>% group_by(planting) %>%
  summarize(avg_planting_to_harvest = mean(DAP, na.rm = TRUE))

plantgro_NFREC_NWG_grain_maturity_200_plants_112kg_N <- plantgro

tops_weight_at_grain_maturity_NFREC_NWG_200_plants_112kg_N <- ggplot(data=plantgro,aes(x=planting,y=CWAD)) +
  geom_boxplot(outlier.colour="black", outlier.shape=16,
               outlier.size=2, notch=FALSE) + 
  geom_text(
    data = plantgro %>% group_by(planting) %>% summarise(avg_planting_to_harvest = round(mean(DAP, na.rm = TRUE), digits = 0)),
    aes(y = avg_planting_to_harvest, label = avg_planting_to_harvest), 
    position = position_dodge(width = 1), 
    vjust = -0, 
    size = 6, 
    stat = "unique", 
    parse = TRUE
  ) +
  ylab(expression(Tops~Weight~"("*kg~dm~ha^{-1}*")")) +
  xlab("Planting Date (dd-mm) and Average Days to Harvest") +
  ggtitle("(f) Tops Weight at Grain Maturity - 'NWG 2730'") + 
  theme_bw() +
  theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank()) +
  theme(text = element_text(size=global_size), legend.position="none", plot.title = element_text(hjust = 0.5))
tops_weight_at_grain_maturity_NFREC_NWG_200_plants_112kg_N
grain_weight_at_grain_maturity_NFREC_NWG_200_plants_112kg_N <- ggplot(data=plantgro,aes(x=planting,y=GWAD)) +
  geom_boxplot(outlier.colour="black", outlier.shape=16,
               outlier.size=2, notch=FALSE) + 
  geom_text(
    data = plantgro %>% group_by(planting) %>% summarise(avg_planting_to_harvest = round(mean(DAP, na.rm = TRUE), digits = 0)),
    aes(y = avg_planting_to_harvest, label = avg_planting_to_harvest), 
    position = position_dodge(width = 1), 
    vjust = -0, 
    size = 6, 
    stat = "unique", 
    parse = TRUE
  ) +
  ylab(expression(Grain~Weight~"("*kg~dm~ha^{-1}*")")) +
  xlab("Planting Date (dd-mm) and Average Days to Harvest") +
  ggtitle("(d) Grain Weight at Grain Maturity - 'NWG 2730'") + 
  theme_bw() +
  theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank()) +
  theme(text = element_text(size=global_size), legend.position="none", plot.title = element_text(hjust = 0.5))
grain_weight_at_grain_maturity_NFREC_NWG_200_plants_112kg_N

summary <- plantgro %>%
  group_by(TRNO) %>%
  summarize(
    location = 'Live Oak (NFREC)',
    cultivar = 'NWG 2730',
    density = '200/m2 (18.6/sqft)', nitrogen = '112 Kg/ha (100 LB/acre)', 
