setwd("C:/DSSAT48/Hemp")
batch_file_path <- paste0(getwd(),'/DSSBatch.V48')
write_dssbatch(x=paste0(filename,'.HMX'), trtno=1:9, file_name = batch_file_path)
run_dssat()
plantgro <- read_output('PlantGro.OUT') %>%
  filter(GSTD == 8)  %>%
  mutate(planting=factor(TRNO,labels=planting_dates))

plantgro_MREC_IHW_grain_maturity_160_plants_224kg_N <- plantgro

#print average time to harvest/flowering per planting date
print("MREC - IH Williams - At Grain Maturity")
avg_planting_to_harvest <- plantgro %>% group_by(planting) %>%
  summarize(avg_planting_to_harvest = mean(DAP, na.rm = TRUE))
avg_planting_to_harvest
#test <- as.data.frame(avg_planting_to_harvest[,2])
#test[2]

tops_weight_at_grain_maturity_MREC_IHWilliams_160_plants_224kg_N <- ggplot(data=plantgro,aes(x=planting,y=CWAD)) +
  geom_boxplot(outlier.colour="black", outlier.shape=16,
               outlier.size=2, notch=FALSE) + 
  geom_text(
    data = plantgro %>% group_by(planting) %>% summarise(avg_planting_to_harvest = round(mean(DAP, na.rm = TRUE), digits = 0)),
    aes(y = avg_planting_to_harvest, label = avg_planting_to_harvest), 
    position = position_dodge(width = 1), 
    vjust = -0, 
    size = 6, 
    stat = "unique", 
    parse = TRUE
  ) +
  ylab(expression(Tops~Weight~"("*kg~dm~ha^{-1}*")")) +
  xlab("Planting Date (dd-mm) and Average Days to Harvest") +
  ggtitle("(e) Tops Weight at Grain Maturity - 'IH Williams'") + 
  theme_bw() +
  theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank()) +
  theme(text = element_text(size=global_size), legend.position="none", plot.title = element_text(hjust = 0.5))
tops_weight_at_grain_maturity_MREC_IHWilliams_160_plants_224kg_N

grain_weight_at_grain_maturity_MREC_IHWilliams_160_plants_224kg_N <- ggplot(data=plantgro,aes(x=planting,y=GWAD)) +
  geom_boxplot(outlier.colour="black", outlier.shape=16,
               outlier.size=2, notch=FALSE) + 
  ylab(expression(Grain~Weight~"("*kg~dm~ha^{-1}*")")) +
  geom_text(
    data = plantgro %>% group_by(planting) %>% summarise(avg_planting_to_harvest = round(mean(DAP, na.rm = TRUE), digits = 0)),
    aes(y = avg_planting_to_harvest, label = avg_planting_to_harvest), 
    position = position_dodge(width = 1), 
    vjust = -0, 
    size = 6, 
    stat = "unique", 
    parse = TRUE
  ) +
  xlab("Planting Date (dd-mm) and Average Days to Harvest") +
  ggtitle("(c) Grain Weight at Grain Maturity - 'IH Williams'") + 
  theme_bw() +
  theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank()) +
  theme(text = element_text(size=global_size), legend.position="none", plot.title = element_text(hjust = 0.5))
grain_weight_at_grain_maturity_MREC_IHWilliams_160_plants_224kg_N

summary <- plantgro %>%
  group_by(TRNO) %>%
  summarize(
    location = 'Apopka (MREC)',
    cultivar = 'IH Williams',
    density = '160/m2 (14.8/sqft)', nitrogen = '224 Kg/ha (200 LB/acre)', 
    harvest = 'Grain Maturity',
    Mean_CWAD = mean(CWAD, na.rm = TRUE),
    Median_CWAD = median(CWAD, na.rm = TRUE),
    SD_CWAD = sd(CWAD, na.rm = TRUE),
    Min_CWAD = min(CWAD, na.rm = TRUE),
    Max_CWAD = max(CWAD, na.rm = TRUE),
    Mean_GWAD = mean(GWAD, na.rm = TRUE),
    Median_GWAD = median(GWAD, na.rm = TRUE),
    SD_GWAD = sd(GWAD, na.rm = TRUE),
    Min_GWAD = min(GWAD, na.rm = TRUE),
    Max_GWAD = max(GWAD, na.rm = TRUE),
    Count = n()
  )

plantgro$location = 'Apopka (MREC)'
plantgro$cultivar = 'IH Williams'
plantgro$density = '160/m2 (14.8/sqft)'
plantgro$nitrogen = '224 Kg/ha (200 LB/acre)'
plantgro$harvest = 'Grain Maturity'
tops_weight_combined_full <- bind_rows(tops_weight_combined_full, plantgro)

summary$planting <- planting_dates
planting_to_harvest <- plantgro %>% group_by(planting) %>%
  summarize(avg_planting_to_harvest = mean(DAP, na.rm = TRUE))
summary <- 
  left_join(
    summary,
    planting_to_harvest,
    by = NULL,
    copy = FALSE,
    suffix = c(".x", ".y"),
    keep = NULL
  )
summary
summary_at_grain_maturity_MREC_IHWilliams_160_plants_224kg_N <- summary
summary_combined <- rbind(summary_combined, summary)


